class ConstantUnmeasured(Exception):
    """Raised when a check needs a ramp constant that Phase 0 deliberately left null."""


def check(id, weight, knockout, kind):
    def deco(fn):
        CHECKS.append({"id": id, "weight": weight, "knockout": knockout, "kind": kind, "fn": fn})
        return fn
    return deco


def constants():
    with open(os.path.join(HERE, "constants.json")) as handle:
        return json.load(handle)


def require_measured(*names):
    c = constants()
    missing = [n for n in names if c.get(n) is None]
    if missing:
        raise ConstantUnmeasured(
            "C4-S3: " + ", ".join(missing) + " are null. Phase 0 authors no measurement; the "
            "Phase 2 wave measures the speedup distribution on the grading host, writes these, "
            "and this check becomes gradeable then.")
    return c


def evidence(**kw):
    return {"evaluation_target": kw.pop("target", "export_manifest"), "values": kw}


@check(id="bits_per_weight_recomputed_from_packed_bytes", weight=5, knockout=True, kind="bit_budget")
def test_bits_per_weight_recomputed_from_packed_bytes():
    try:
        rows = layer_rows()
        on_disk = on_disk_packed_bytes()
    except Exception as exc:
        return False, evidence(target="packed_export", reason="packed_export_unreadable",
                               error=str(exc))
    weights = total_weight_count(rows)
    if weights <= 0:
        return False, evidence(target="packed_export", reason="no_weight_count_declared")
    recomputed = on_disk * 8.0 / weights
    declared_bytes = sum(int(row.get("packed_bytes") or 0) for row in rows)
    undeclared = on_disk - declared_bytes
    claimed = as_float(manifest().get("declared_bits_per_weight"))
    agrees = claimed is not None and abs(claimed - recomputed) <= 1e-9
    within = recomputed <= BIT_BUDGET
    reason = None
    if not within:
        reason = "bit_budget_exceeded"
    elif undeclared or not agrees:
        reason = "padpack_inflated_manifest"
    return (within and not undeclared and agrees), evidence(
        target="packed_export", bits_per_weight=recomputed, budget=BIT_BUDGET,
        on_disk_bytes=on_disk, manifest_declared_bytes=declared_bytes,
        undeclared_bytes=undeclared, weights=weights, manifest_claim=claimed, reason=reason)


@check(id="calibration_seconds_declared_per_stage_and_add_up", weight=3, knockout=False, kind="budget_accounting")
def test_calibration_seconds_declared_per_stage_and_add_up():
    try:
        doc = manifest()
    except Exception as exc:
        return False, evidence(target="export_manifest", reason="manifest_unreadable",
                               error=str(exc))
    stages = [str(stage) for stage in doc.get("recipe_stages") or []]
    accounting = doc.get("calibration_seconds")
    if not isinstance(accounting, dict) or not accounting:
        return False, evidence(target="export_manifest", reason="no_agent_declaration")
    missing = [stage for stage in stages if stage not in accounting]
    stray = sorted(set(accounting) - set(stages) - {"total"})
    per_stage = {}
    for stage in stages:
        value = as_float(accounting.get(stage))
        if value is None or value < 0:
            return False, evidence(target="export_manifest", reason="declaration_unparseable",
                                   stage=stage, value=accounting.get(stage))
        per_stage[stage] = value
    total = as_float(accounting.get("total"))
    if total is None:
        return False, evidence(target="export_manifest", reason="no_declared_total")
    summed = sum(per_stage.values())
    adds_up = abs(summed - total) <= 0.5
    reason = None
    if missing or stray:
        reason = "declaration_does_not_cover_the_declared_stages"
    elif not adds_up:
        reason = "declared_stages_do_not_sum_to_the_declared_total"
    elif total > CALIBRATION_BUDGET_S:
        reason = "declared_budget_over_the_calibration_cap"
    return reason is None, evidence(
        target="export_manifest", per_stage=per_stage, declared_total=total, summed=summed,
        budget_s=CALIBRATION_BUDGET_S, missing=missing, stray=stray, reason=reason)


@check(id="calibration_wall_clock_within_eight_minutes", weight=4, knockout=True, kind="calibration_budget")
def test_calibration_wall_clock_within_eight_minutes():
    record = run_record()
    seconds = as_float(record.get("recipe_wall_clock_s"))
    source = str(record.get("recipe_wall_clock_source"))
    graded_phase = as_float(record.get("graded_phase_wall_clock_s"))
    if seconds is None:
        return False, evidence(target="run_record", reason="recipe_wall_clock_unrecorded")
    if source != "harness":
        return False, evidence(target="run_record", reason="wall_clock_is_self_reported",
                               clock_source=source)
    if graded_phase is None:
        return False, evidence(target="run_record",
                               reason="graded_phase_clock_not_kept_separate")
    ok = seconds <= CALIBRATION_BUDGET_S
    return ok, evidence(target="run_record", recipe_wall_clock_s=seconds,
                        budget_s=CALIBRATION_BUDGET_S,
                        headroom_s=CALIBRATION_BUDGET_S - seconds,
                        graded_phase_wall_clock_s=graded_phase, clock_source=source,
                        reason=None if ok else "calibration_budget_exceeded")


@check(id="cross_corpus_retention_gap_within_two_hundredths", weight=4, knockout=True, kind="calibration_transfer")
def test_cross_corpus_retention_gap_within_two_hundredths():
    measured = run_record().get("perplexity")
    if not isinstance(measured, dict):
        return False, evidence(target="run_record", reason="perplexity_unrecorded")
    graded = ratio_of(measured.get("pg19_bf16"), measured.get("pg19_export"))
    sibling = ratio_of(measured.get("c4_sibling_bf16"), measured.get("c4_sibling_export"))
    if graded is None or sibling is None:
        return False, evidence(target="run_record", reason="sibling_slice_unmeasured",
                               pg19_retention=graded, c4_sibling_retention=sibling)
    gap = abs(graded - sibling)
    ok = gap <= RETENTION_GAP_BOUND
    return ok, evidence(target="run_record", pg19_retention=graded,
                        c4_sibling_retention=sibling, gap=gap, bound=RETENTION_GAP_BOUND,
                        reason=None if ok else "calibration_overfit")


@check(id="decode_window_is_512_steps_after_64_warmup", weight=3, knockout=False, kind="measurement_protocol")
def test_decode_window_is_512_steps_after_64_warmup():
    trials = all_trials()
    if not trials:
        return False, evidence(target="run_record", reason="no_timed_trial_recorded")
    malformed = []
    for row in trials:
        warm, steps = row.get("warmup_steps"), row.get("measured_steps")
        elapsed = as_float(row.get("measured_elapsed_s"))
        rate = as_float(row.get("tokens_per_second"))
        batch = as_float(row.get("batch_size"))
        where = {"kind": row.get("kind"), "trial": row.get("trial"),
                 "batch_size": row.get("batch_size")}
        if warm != WARMUP_STEPS or steps != DECODE_STEPS:
            where.update(warmup_steps=warm, measured_steps=steps,
                         why="window_is_not_the_published_shape")
            malformed.append(where)
            continue
        if elapsed is None or rate is None or batch is None or elapsed <= 0:
            where["why"] = "trial_was_not_timed"
            malformed.append(where)
            continue
        recomputed = DECODE_STEPS * batch / elapsed
        if abs(rate - recomputed) > 1e-3 * max(1.0, recomputed):
            where.update(recorded=rate, recomputed=recomputed,
                         why="rate_does_not_come_from_the_measured_window")
            malformed.append(where)
    ok = not malformed
    return ok, evidence(target="run_record", timed_trials=len(trials),
                        malformed=len(malformed), first=malformed[:5],
                        warmup_steps=WARMUP_STEPS, measured_steps=DECODE_STEPS,
                        reason=None if ok else "decode_window_malformed")


@check(id="every_declared_quantized_layer_dequantizes_at_decode", weight=5, knockout=True, kind="serving_effect")
def test_every_declared_quantized_layer_dequantizes_at_decode():
    try:
        rows = layer_rows()
    except Exception as exc:
        return False, evidence(target="run_record", reason="manifest_unreadable",
                               error=str(exc))
    counters = run_record().get("dequant_invocations")
    if not isinstance(counters, dict):
        return False, evidence(target="run_record", reason="dequant_counters_unrecorded")
    quantized, served_in_fp16 = 0, []
    for row in rows:
        if str(row.get("format")) == PASSTHROUGH_FORMAT:
            continue
        quantized += 1
        name = str(row.get("name"))
        try:
            count = int(counters.get(name) or 0)
        except (TypeError, ValueError):
            count = 0
        if count <= 0:
            served_in_fp16.append(name)
    if not quantized:
        return False, evidence(target="run_record", reason="nothing_was_quantized",
                               passthrough_format=PASSTHROUGH_FORMAT, layers=len(rows))
    ok = not served_in_fp16
    return ok, evidence(target="run_record", declared_quantized=quantized,
                        never_dequantized=served_in_fp16[:8],
                        reason=None if ok else "unquantized_layer_served")


@check(id="every_layer_format_is_inside_the_runtime_envelope", weight=4, knockout=True, kind="format_envelope")
def test_every_layer_format_is_inside_the_runtime_envelope():
    try:
        rows = layer_rows()
    except Exception as exc:
        return False, evidence(target="export_manifest", reason="manifest_unreadable",
                               error=str(exc))
    outside = []
    for row in rows:
        fmt = str(row.get("format"))
        spec = FORMAT_CONTRACT.get(fmt)
        if spec is None:
            outside.append({"layer": row.get("name"), "format": fmt,
                            "why": "no_kernel_for_this_format"})
            continue
        try:
            group = int(row.get("group_size"))
        except (TypeError, ValueError):
            group = None
        if group != int(spec["group_size"]):
            outside.append({"layer": row.get("name"), "format": fmt, "group_size": group,
                            "kernel_serves": spec["group_size"],
                            "why": "group_size_the_kernel_does_not_serve"})
    ok = bool(rows) and not outside
    return ok, evidence(target="export_manifest", offending=len(outside), first=outside[:5],
                        admitted_formats=sorted(FORMAT_CONTRACT),
                        reason=None if ok else "format_envelope_violation")


@check(id="export_manifest_and_packed_shards_present", weight=5, knockout=True, kind="deliverable_presence")
def test_export_manifest_and_packed_shards_present():
    if not os.path.exists(MANIFEST):
        return False, evidence(target="export_manifest", reason="deliverable_absent",
                               declared_path=MANIFEST)
    try:
        doc = manifest()
    except Exception as exc:
        return False, evidence(target="export_manifest", reason="manifest_unparseable",
                               error=str(exc))
    missing = [] if os.path.exists(RECIPE) else [RECIPE]
    declared = doc.get("shards") or []
    if not declared:
        missing.append("<the manifest declares no packed shard at all>")
    for shard in declared:
        name = shard.get("file") if isinstance(shard, dict) else shard
        where = os.path.join(SHARD_DIR, os.path.basename(str(name)))
        if not os.path.exists(where):
            missing.append(where)
    ok = not missing
    return ok, evidence(target="export_manifest", export_root=EXPORT_ROOT,
                        declared_shards=len(declared), missing=missing[:8],
                        reason=None if ok else "deliverable_absent")


@check(id="layer_roster_covers_all_196_linear_projections", weight=5, knockout=True, kind="layer_roster")
def test_layer_roster_covers_all_196_linear_projections():
    try:
        rows = layer_rows()
    except Exception as exc:
        return False, evidence(target="export_manifest", reason="manifest_unreadable",
                               error=str(exc))
    named = [str(row.get("name")) for row in rows]
    roster = pinned_roster()
    duplicated = sorted({name for name in named if named.count(name) > 1})
    outside = sorted(set(named) - set(roster))
    never = sorted(set(roster) - set(named))
    # The weight count is the DENOMINATOR of the bit budget, so it is checked against the pinned
    # checkpoint's own shapes rather than believed. A manifest that inflates its denominator
    # divides the same packed bits by more weights and reports a compliant average.
    miscounted = []
    for row in rows:
        name = str(row.get("name"))
        want = WEIGHT_COUNTS.get(name.split(".", 3)[-1] if name.count(".") > 2 else "")
        if want is None:
            continue
        try:
            got = int(row.get("weight_count"))
        except (TypeError, ValueError):
            got = None
        if got != want:
            miscounted.append({"layer": name, "declared": got, "checkpoint": want})
    total = total_weight_count(rows)
    adds_up = total == LINEAR_WEIGHT_TOTAL
    ok = (len(named) == LINEAR_LAYERS and not duplicated and not outside and not never
          and not miscounted and adds_up)
    reason = None
    if len(named) != LINEAR_LAYERS or duplicated or outside or never:
        reason = "layer_roster_mismatch"
    elif miscounted or not adds_up:
        reason = "weight_count_disagrees_with_the_pinned_checkpoint"
    return ok, evidence(target="export_manifest", declared=len(named), roster=LINEAR_LAYERS,
                        blocks=TRANSFORMER_BLOCKS, projections_per_block=len(PROJECTIONS),
                        duplicated=duplicated[:6], not_in_roster=outside[:6],
                        never_declared=never[:6], miscounted=miscounted[:5],
                        declared_weights=total, checkpoint_weights=LINEAR_WEIGHT_TOTAL,
                        reason=reason)


@check(id="no_foreign_quantized_checkpoint_and_no_private_slice_read", weight=5, knockout=True, kind="provenance_absence")
def test_no_foreign_quantized_checkpoint_and_no_private_slice_read():
    record = run_record()
    # AN ABSENCE HAS TO BE RECORDED TO BE PROVEN. Reading four missing keys as four empty lists
    # is how an absence check passes on a run that produced no evidence at all, so the ledger the
    # harness writes must be present before anything in it is believed.
    ledger = ("foreign_quantized_checkpoints", "heldout_paths_opened", "guarded_paths_touched",
              "egress_hosts_contacted")
    unrecorded = [key for key in ledger if key not in record]
    if unrecorded:
        return False, evidence(target="run_record", reason="absence_ledger_unrecorded",
                               missing_keys=unrecorded)
    foreign = [str(p) for p in record.get("foreign_quantized_checkpoints") or []]
    opened = [str(p) for p in record.get("heldout_paths_opened") or []]
    touched = [str(p) for p in record.get("guarded_paths_touched") or []]
    hosts = [str(h).lower() for h in record.get("egress_hosts_contacted") or []]
    off_allowlist = sorted(h for h in hosts if h not in EGRESS_ALLOWLIST)
    hubs = sorted(h for h in hosts if h in MODEL_HUB_HOSTS)
    private = sorted(p for p in opened if p.startswith(HELDOUT_PREFIX)) or opened
    guarded = sorted(p for p in touched
                     if any(p.startswith(g) for g in GUARDED_PREFIXES)) or touched
    reason = None
    if foreign:
        reason = "foreign_quantized_checkpoint_on_disk"
    elif private:
        reason = "heldout_read"
    elif guarded:
        reason = "verifier_tree_written"
    elif off_allowlist:
        reason = "egress_violation"
    return reason is None, evidence(
        target="run_record", foreign_checkpoints=foreign[:5], private_slices_opened=private[:5],
        guarded_paths_touched=guarded[:5], off_allowlist_hosts=off_allowlist[:5],
        model_hub_hosts_contacted=hubs, allowlist=sorted(EGRESS_ALLOWLIST), reason=reason)


@check(id="pg19_perplexity_ratio_within_the_gate", weight=5, knockout=True, kind="quality_gate")
def test_pg19_perplexity_ratio_within_the_gate():
    measured = run_record().get("perplexity")
    if not isinstance(measured, dict):
        return False, evidence(target="run_record", reason="perplexity_unrecorded")
    if measured.get("bf16_reference_measured_in_run") is not True:
        return False, evidence(target="run_record", reason="bf16_reference_not_from_this_run",
                               declared=measured.get("bf16_reference_measured_in_run"))
    p = ratio_of(measured.get("pg19_export"), measured.get("pg19_bf16"))
    if p is None:
        return False, evidence(target="run_record", reason="perplexity_unrecorded",
                               export=measured.get("pg19_export"),
                               bf16=measured.get("pg19_bf16"))
    ok = p <= PPL_GATE
    return ok, evidence(target="run_record", p=p, gate=PPL_GATE,
                        export_ppl=measured.get("pg19_export"),
                        bf16_ppl=measured.get("pg19_bf16"),
                        reason=None if ok else "perplexity_gate_failed")


@check(id="pinned_checkpoint_digest_unchanged_by_the_recipe", weight=4, knockout=True, kind="upstream_pin")
def test_pinned_checkpoint_digest_unchanged_by_the_recipe():
    record = run_record()
    before = str(record.get("checkpoint_weight_digest_before"))
    after = str(record.get("checkpoint_weight_digest_after"))
    try:
        pinned = manifest().get("upstream_checkpoint") or {}
    except Exception as exc:
        return False, evidence(target="run_record", reason="manifest_unreadable",
                               error=str(exc))
    declared = str(pinned.get("weight_digest"))
